const decode=text=>text.replace(/&(?:amp|lt|gt|quot|#39);/g,entity=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&#39;':"'"})[entity]);
const attrs=tag=>Object.fromEntries([...tag.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m=>[m[1],decode(m[2])]));
const box=a=>({x:+a.x,y:+a.y,width:+a.width,height:+a.height});
function tree(svg){const root={tag:'root',attrs:{},children:[]};const stack=[root];for(const match of svg.matchAll(/<[^>]+>|[^<]+/g)){const token=match[0];if(token.startsWith('</')){stack.pop();continue;}if(token.startsWith('<!')||token.startsWith('<?'))continue;if(token.startsWith('<')){const tag=token.match(/^<([\w:-]+)/)?.[1];if(!tag)continue;const node={tag,attrs:attrs(token),children:[]};stack.at(-1).children.push(node);if(!token.endsWith('/>'))stack.push(node);}else stack.at(-1).children.push({tag:'#text',text:decode(token),children:[]});}return root;}
const descendants=(node,predicate)=>node.children.flatMap(child=>[...(predicate(child)?[child]:[]),...descendants(child,predicate)]);
const textContent=node=>node.tag==='#text'?node.text:node.children.map(textContent).join('');
const texts=node=>descendants(node,n=>n.tag==='text').map(n=>({content:textContent(n),x:+n.attrs.x,y:+n.attrs.y,font:+n.attrs['font-size'],anchor:n.attrs['text-anchor']||'start'}));
function measure(svg){const dom=tree(svg);const nodes=descendants(dom,n=>n.tag==='g'&&n.attrs?.['data-node-id']).map(node=>({id:node.attrs['data-node-id'],bounds:box(descendants(node,n=>n.tag==='rect')[0].attrs),texts:texts(node)}));const edges=descendants(dom,n=>n.tag==='path'&&n.attrs?.['data-edge-key']!==undefined).map(n=>({key:+n.attrs['data-edge-key'],from:n.attrs['data-edge-from'],to:n.attrs['data-edge-to'],points:n.attrs['data-composition-points'].split(';').map(p=>p.split(',').map(Number)),d:n.attrs.d,junction:n.attrs['data-composition-junction']||null}));const labels=descendants(dom,n=>n.tag==='g'&&n.attrs?.['data-edge-key']!==undefined).map(n=>({key:+n.attrs['data-edge-key'],bounds:box(descendants(n,c=>c.tag==='rect')[0].attrs),texts:texts(n)}));return {viewBox:descendants(dom,n=>n.tag==='svg')[0].attrs.viewBox.split(' ').map(Number),nodes,edges,labels,frames:descendants(dom,n=>n.tag==='rect'&&n.attrs?.['data-lifecycle-frame']!==undefined).map(n=>box(n.attrs)),junctions:descendants(dom,n=>n.tag==='circle'&&n.attrs?.['data-lifecycle-junction']!==undefined).map(n=>[+n.attrs.cx,+n.attrs.cy]),texts:texts(dom)};}

const temporary=await mkdtemp(path.join(os.tmpdir(),'phoenix-lifecycle-oracle-'));const cases=[];
try{for(const [contract,name,document] of documents.map(c=>[c.contract,c.name,c.document])){const sourceRoot=sources.find(s=>s[0]===contract)[1];const source=`${sourceRoot}/renderers/lifecycle/render-lifecycle.mjs`;const inputFile=path.join(temporary,`${contract}-${name}.json`);const outputFile=path.join(temporary,`${contract}-${name}.html`);await writeFile(inputFile,JSON.stringify(document));const run=spawnSync(process.execPath,[path.join(root,source),inputFile,outputFile],{cwd:root,encoding:'utf8',env:{...process.env,ARCHIFY_DIAGNOSTIC_FORMAT:'json',ARCHIFY_QUALITY_PROFILE:document.meta.quality_profile}});assert.equal(run.signal,null,`${name}: source signalled`);const entry={contract,name,source,sourceSha256:digest(await readFile(path.join(root,source))),document,ok:run.status===0};if(entry.ok){const html=await readFile(outputFile,'utf8');const svg=html.match(/<svg\b[^>]*viewBox="0 0 [^"]+"[\s\S]*?<\/svg>/)?.[0];assert(svg,`${name}: actual SVG missing`);entry.svgFile=`${contract}-${name}.svg`;entry.svgSha256=digest(svg);entry.geometry=measure(svg);await writeFile(new URL(entry.svgFile,import.meta.url),svg);}else{entry.diagnostics=JSON.parse(run.stdout.trim()||run.stderr.trim()).diagnostics;entry.stderr=run.stderr.trim();}cases.push(entry);}}finally{await rm(temporary,{recursive:true,force:true});}
await writeFile(new URL('./oracle.json',import.meta.url),`${JSON.stringify({format:1,cases},null,2)}\n`);
console.log(`Wrote ${cases.length} lifecycle cases, ${cases.filter(c=>c.ok).length} accepted; exact SVG retained.`);
